UPDATE tool_execution_records
SET status = 'RUNNING', argument_fingerprint = #{argumentFingerprint},
    result_json = NULL, error_message = NULL, started_at = NOW(),
    completed_at = NULL, updated_at = NOW()
WHERE task_uuid = #{taskUuid}
  AND idempotency_key = #{idempotencyKey}
  AND argument_fingerprint = #{argumentFingerprint}
  AND status = 'FAILED'
